import{F as e,I as t,R as n,et as r,n as i}from"./chunks/framework.Bs4wm_X5.js";import{d as a}from"./chunks/theme.DtloWbYQ.js";import{dr as o,fr as s}from"./chunks/assets.BpWoSz4B.js";import{t as c}from"./chunks/AbcRender.tSiVtjqu.js";import{t as l}from"./chunks/ChromaProfile.qWMoDcYG.js";var u=JSON.parse(`{"title":"Unison and octave","description":"Intervals inside the same pitch class","frontmatter":{"title":"Unison and octave","description":"Intervals inside the same pitch class","cover":"garmin-b.jpg","date":"2021-09-10T00:00:00.000Z"},"headers":[],"relativePath":"theory/intervals/unison-octave/index.md","filePath":"theory/intervals/unison-octave/index.md","lastUpdated":1790102922000}`),d={name:`theory/intervals/unison-octave/index.md`};function f(i,u,d,f,p,m){let h=c,g=l,_=a;return r(),e(`div`,null,[u[0]||=t(`<p>An <strong>interval</strong> is the relationship between two musical sounds in terms of pitch — the terrain we navigate every time we jam, harmonize, or sing in a choir. Intervals occur <strong>simultaneously</strong> (two notes sounding together — <em>harmonic</em>, vertical) and <strong>sequentially</strong> (one note following another — <em>melodic</em>, horizontal).</p><p>Two intervals anchor that entire terrain: <strong>unison</strong> and <strong>octave</strong>. They are the reference points from which all other intervals derive their meaning — and the only intervals where both notes share the same <strong>pitch class</strong>, the same color in Chromatone.</p><table tabindex="0"><thead><tr><th>At a glance</th><th>Unison (P1)</th><th>Octave (P8)</th></tr></thead><tbody><tr><td>Frequency ratio</td><td>1:1</td><td>2:1</td></tr><tr><td>Semitones</td><td>0</td><td>12</td></tr><tr><td>Cents</td><td>0</td><td>1200</td></tr><tr><td>Pitch class / chroma</td><td>same</td><td>same</td></tr><tr><td>On the spectrogram</td><td>one reinforced band</td><td>parallel same-color lines</td></tr></tbody></table><h2 id="unison-p1" tabindex="-1">Unison P1 <a class="header-anchor" href="#unison-p1" aria-label="Permalink to “Unison P1”">​</a></h2>`,4),n(h,{abc:`[A4A4] AA`}),n(g,{chroma:`100000000000`}),u[1]||=t(`<p><strong>Unison</strong> is two or more musical parts sounding either the same pitch, or pitches separated by one or more octaves, usually at the same time. <strong>Perfect unison</strong> (also a <strong>prime</strong> or <strong>perfect prime</strong>; German <em>Unisono</em>, <em>Einklang</em>, or <em>Prime</em>) is the (pseudo-)interval between a tone and its exact duplication — C–C, as differentiated from the second, C–D.</p><ul><li><strong>Ratio 1:1</strong> — 0 half steps, 0 cents. Two parts, one frequency.</li><li><strong>The most consonant interval</strong> — while the <strong>near unison</strong> is the most <em>dissonant</em>: tones a few hertz apart produce slow loudness <strong>beats</strong>, and differences of a few tens of hertz fall inside one critical band of the ear as maximal roughness (Plomp &amp; Levelt, 1965).</li><li><strong>The easiest interval to tune</strong> — precisely because those beats slow down and disappear at exactly 1:1. Ensemble players and piano tuners tune unisons by ear this way.</li><li><strong>Still two sources.</strong> Even in perfect unison we perceive separate voices: they arrive from different locations and carry different <strong>timbres</strong> — different waveforms with the same fundamental frequency but different amplitudes of higher harmonics.</li></ul><blockquote><p><strong>Feel it:</strong> when a choir section sings together, voices merge into a wall of unified sound; an orchestra doubling one line gains thickness and authority; a rock band doubling a riff in unison gets a fatter tone. The parts fuse into reinforcement and unity — yet the blend is richer than any single voice.</p></blockquote><blockquote><p><strong>Fact:</strong> most piano keys strike <strong>two or three strings tuned in unison</strong>; Balinese gamelan deliberately tunes paired instruments a few hertz apart so the &quot;unison&quot; shimmers with slow beats called <strong>ombak</strong> (&quot;wave&quot;) — near-unison used as beauty, not error.</p></blockquote><p><strong>Chromatone view.</strong> On the spectrogram, unison appears as two perfectly aligned lines of color occupying the same frequency — a single, reinforced band. No tension, no movement: pure alignment. That is exactly why unison feels like home.</p><h2 id="octave-p8" tabindex="-1">Octave P8 <a class="header-anchor" href="#octave-p8" aria-label="Permalink to “Octave P8”">​</a></h2>`,6),n(h,{abc:`[A4a] Aa`}),u[2]||=t(`<p>An <strong>octave</strong> (Latin <em>octavus</em>: eighth; also <strong>perfect octave</strong> or <strong>diapason</strong>, from Greek <em>dia pasōn</em>, &quot;through all [the strings]&quot;) is the interval between one musical pitch and another with <strong>double its frequency</strong>: A 220 Hz → A 440 Hz → A 880 Hz, doubling by 2ⁿ in both directions without limit. This octave relationship is a natural phenomenon, referred to as the &quot;basic miracle of music,&quot; the use of which is &quot;common in most musical systems.&quot;</p><ul><li><strong>Nature&#39;s first interval.</strong> The step between the 1st and 2nd harmonics of the harmonic series is an octave — as is every 2→4, 3→6, 4→8 step above it.</li><li><strong>1200 cents.</strong> Human pitch perception is <strong>logarithmic</strong> — we hear ratios, not hertz differences — so intervals are measured in <strong>cents</strong>, the unit Alexander John Ellis introduced in his 1885 English edition of Helmholtz&#39;s <em>On the Sensations of Tone</em>: one octave = 1200 cents, one equal-tempered semitone = 100.</li><li><strong>Same color, new register.</strong> Because pitch perception is periodic, the &quot;color&quot; (<strong>chroma</strong>) of all notes an octave apart seems circularly equivalent, gathering them into one <strong>pitch class</strong>. Psychologists picture pitch as a <strong>helix</strong>: height climbs forever while chroma circles every 12 semitones (Revesz, 1913; Shepard, 1982).</li></ul><blockquote><p><strong>Feel it:</strong> octaves are separation yet unity — different registers, still &quot;together.&quot; Doubling a melody in octaves adds brilliance and power, reinforced bass lines hit harder, open spacious harmonies appear, and sudden octave jumps create drama.</p></blockquote><img src="`+s+`"><p>To emphasize that it is one of the <strong>perfect intervals</strong> (together with unison, perfect fourth, and perfect fifth), the octave is designated <strong>P8</strong>.</p><p><strong>Chromatone view.</strong> On the spectrogram, octaves appear as <strong>parallel lines of the same color</strong>, spaced equally apart (equally, because the frequency axis is logarithmic). The pattern repeats at each octave level — the octave is a true <strong>cycle</strong>, which is why we can say &quot;C&quot; in any octave and mean essentially the same thing.</p>`,6),n(g,{chroma:`100000000000`}),u[3]||=t(`<p><em>The same chroma profile lights up for both notes of an octave: different height, identical color.</em></p><h2 id="octave-equivalence-who-hears-the-cycle" tabindex="-1">Octave equivalence: who hears the cycle? <a class="header-anchor" href="#octave-equivalence-who-hears-the-cycle" aria-label="Permalink to “Octave equivalence: who hears the cycle?”">​</a></h2><p>After the unison, the octave is the simplest interval in music. The human ear tends to hear both notes as essentially &quot;the same,&quot; due to closely related harmonics — in fact <strong>every harmonic of the higher note is also a harmonic of the lower one</strong>, so notes an octave apart &quot;ring&quot; together. The interval is so natural that when men and women are asked to sing in unison, they typically sing in octave.</p><p>This perceived sameness of pitches one or more octaves apart is called <strong>octave equivalence</strong>. It is why notes an octave apart share one letter name in Western notation, and why &quot;scales are uniquely defined by specifying the intervals within an octave.&quot;</p><h3 id="the-evidence" tabindex="-1">The evidence <a class="header-anchor" href="#the-evidence" aria-label="Permalink to “The evidence”">​</a></h3><ul><li><strong>Human infants</strong>, before language development, already group octave-related tones by chroma (Demany &amp; Armand, 1984).</li><li><strong>Rats</strong> generalize across octaves (Blackwell &amp; Schlosberg, 1943; confirmed with modern methods by Wagner et al., 2024), and <strong>rhesus monkeys</strong> recognize melodies transposed by an octave (Wright et al., 2000) — evidence that octave perception is deep in mammalian hearing, plausibly tied to harmonic vocal structures.</li><li><strong>Not everyone, though:</strong> European starlings (Cynx, 1993), black-capped chickadees, and common marmosets (Wagner et al., 2023) fail standard octave-equivalence tests — the trait is widespread, but not universal across species.</li><li><strong>The brain files octaves under one category.</strong> fMRI adaptation shows cortical populations tuned to pitch <strong>chroma</strong> respond alike to octave-related tones (Moerel et al., 2014), and auditory attention automatically spreads to octave-related frequencies (Borra et al., 2013).</li><li><strong>Absolute pitch reveals the split:</strong> people with absolute pitch name chroma flawlessly yet often misjudge <em>which octave</em> a note is in — pitch class and pitch height are separate cognitive processes.</li><li><strong>Culture tunes the hardware.</strong> Among the Tsimane&#39; of the Bolivian Amazon, sung reproductions show the universal logarithmic pitch scaling but <strong>no detectable octave equivalence</strong> (Jacoby &amp; McDermott, 2019): musical experience — especially singing — appears to strengthen a cycle the ear is merely ready to hear.</li></ul><img src="`+o+`"><p>A <strong>pitch class</strong> (p.c. or pc) is the set of all pitches a whole number of octaves apart: &quot;The pitch class A stands for all possible As, in whatever octave position.&quot; Pitch therefore has two dimensions — <strong>pitch height</strong> (absolute frequency) and <strong>pitch class</strong> (position within the octave) — and that pair is what makes pitch circular. Thus all C♯s, or all 1s (if C = 0), in any octave belong to one pitch class.</p><blockquote><p>Although there is no formal upper or lower limit to this sequence, only a few of these pitches are audible to the human ear. Yet we can imagine seeing the 40th octave as the frequency gets to the visual spectrum.</p></blockquote><p>Psychologists refer to the quality of a pitch as its <strong>chroma</strong> — an attribute of pitch, just like <strong>hue</strong> is an attribute of color. A pitch class is the sound-world&#39;s &quot;set of all yellow things&quot;: every B, in every octave, is one class, one color.</p><h3 id="the-shepard-tone-the-cycle-made-audible" tabindex="-1">The Shepard tone: the cycle made audible <a class="header-anchor" href="#the-shepard-tone-the-cycle-made-audible" aria-label="Permalink to “The Shepard tone: the cycle made audible”">​</a></h3><p>Stack octaves, fade the top and bottom in and out, and you can rise forever without ever getting higher: the <strong>Shepard tone</strong> (Shepard, 1964, <em>Circularity in Judgments of Relative Pitch</em>; the sliding version is the Shepard–Risset glissando). Its cousin, the <strong>tritone paradox</strong> (Deutsch, 1986), splits listeners into people who hear the same two-tone pair rise and people who hear it fall — direct proof that the brain organizes pitch along an octave circle.</p>`,12),n(_,{video:`BzNzgsAE4F0`}),u[4]||=t(`<h3 id="two-octave-quirks-of-the-brain" tabindex="-1">Two octave quirks of the brain <a class="header-anchor" href="#two-octave-quirks-of-the-brain" aria-label="Permalink to “Two octave quirks of the brain”">​</a></h3><ul><li><strong>Missing fundamental.</strong> Hear only the upper harmonics of a note and the brain reconstructs the bass anyway (first described by Seebeck in 1841; Schouten&#39;s &quot;residue pitch,&quot; 1940). This is why small speakers &quot;play&quot; bass notes they cannot physically reproduce: pitch is a construction, and the octave is its scaffolding.</li><li><strong>Octave stretching.</strong> Judged by ear, octaves at the extremes of the piano sound best slightly <strong>wider</strong> than 2:1 (by a few to a few tens of cents). Piano tuners bake this perceptual stretch into the <strong>Railsback curve</strong>, and string inharmonicity plus sensory dissonance explain much of it (e.g., <em>JASA</em>, 2019). The &quot;perfect&quot; octave is exactly perfect in mathematics — and nearly perfect in the ear.</li></ul><h2 id="notation-naming-the-octaves" tabindex="-1">Notation: naming the octaves <a class="header-anchor" href="#notation-naming-the-octaves" aria-label="Permalink to “Notation: naming the octaves”">​</a></h2><p>Octaves are identified with various naming systems. Among the most common are the <strong>scientific</strong>, <strong>Helmholtz</strong>, <strong>organ-pipe</strong>, and <strong>MIDI</strong> systems. In scientific pitch notation a numeral follows the note name: middle C is <strong>C4</strong> — the fourth C on a standard 88-key piano — and the C an octave higher is C5. Helmholtz uses primes (c′, c″…); MIDI counts semitones (middle C = 60, A440 = 69); and organ <strong>footage</strong> names octaves by pipe length: 8′ sounds as written, 4′ an octave above, 16′ below, 32′ and 64′ into the contra and sub-contra depths.</p><table tabindex="0"><thead><tr><th>Octave name</th><th>Range</th><th>C frequency</th><th>Who lives here</th></tr></thead><tbody><tr><td>Sub-contra</td><td>C0–B0</td><td>16.4–31 Hz</td><td>Lowest audible octave, mostly unused; basso profondo such as Mikhail Zlatopolsky; Tim Storms&#39; record low G−7 (0.189 Hz, 2012) lies far below it</td></tr><tr><td>Contra</td><td>C1–B1</td><td>32.7–61.7 Hz</td><td>Extreme bass voices (Vladimir Miller); 32′ organ stops</td></tr><tr><td>Great</td><td>C2–B2</td><td>65.4–123.5 Hz</td><td>Bass country: basso profondo, bass, baritone; vocal fry dips here; rare low notes of Mariah Carey or Georgia Brown</td></tr><tr><td>Small</td><td>C3–B3</td><td>130.8–246.9 Hz</td><td>Foundation of most vocal music; tenor to soprano harmony roots</td></tr><tr><td>First</td><td>C4–B4</td><td>261.6–493.9 Hz</td><td>The &quot;middle C&quot; octave; most melodic action; tenors and altos at work</td></tr><tr><td>Second</td><td>C5–B5</td><td>523.3–987.8 Hz</td><td>Soprano territory — bright, prominent, carries well</td></tr><tr><td>Third</td><td>C6–B6</td><td>1046.5–1975.5 Hz</td><td>Flutes, violins, coloratura; whistle register begins (above ~1000 Hz the body has few resonators left, so timbre thins)</td></tr><tr><td>Fourth–fifth</td><td>C7–B8</td><td>2093–7902 Hz</td><td>Coloratura extremes and the piano&#39;s top (C8); Georgia Brown&#39;s record G7 lives here</td></tr><tr><td>Sixth and above</td><td>C9+</td><td>8 kHz+</td><td>Whistle tones; past ~20 kHz the cycle leaves the human ear entirely</td></tr></tbody></table><blockquote><p><strong>Records:</strong> in 2004 Georgia Brown (Brazil) documented the Guinness widest <strong>female</strong> vocal range — <strong>8 octaves, G2 to G10</strong>, its top note above human hearing; Tim Storms (USA) holds the overall record at <strong>10 octaves</strong>.</p></blockquote>`,6),n(_,{video:`MzjB8BOBms8`}),u[5]||=t(`<p><strong>The audible window is about ten octaves</strong> (20 Hz – 20 kHz). A piano spans 7⅓ of them (A0–C8); a large organ with a 64′ stop reaches ~8 Hz — vibration felt in the chest more than heard as pitch.</p><p><strong>Practical payoff:</strong> knowing the octave map helps you find your place in the musical texture, avoid competing for the same frequency space, build balanced arrangements, and sing where your voice naturally wants to go.</p><h2 id="beyond-hearing-hypothetical-octaves" tabindex="-1">Beyond hearing: hypothetical octaves <a class="header-anchor" href="#beyond-hearing-hypothetical-octaves" aria-label="Permalink to “Beyond hearing: hypothetical octaves”">​</a></h2><p>The 2:1 cycle does not stop at the ear&#39;s door:</p><ul><li><strong>+40 octaves ≈ light.</strong> Double 440 Hz forty times (≈ 4.8 × 10¹⁴ Hz) and you arrive in the <strong>visible spectrum</strong> (~400–790 THz). Poetically, the eye&#39;s whole window is itself <strong>just under one octave wide</strong> — vision &quot;hears&quot; a single octave of light.</li><li><strong>−4 to −5 octaves ≈ rhythm.</strong> Below roughly 16–20 Hz, pitch dissolves into discrete pulses: the realm of <strong>tempo</strong> (~0.5–8 Hz, i.e. 30–480 BPM). Rhythm and melody turn out to be the same phenomenon at different speeds — a polyrhythm is a polyphony slowed down.</li><li><strong>On Chromatone&#39;s 16-step linear grid</strong> (n/16, n ∈ [16, 32]) mapped to 12-TET pitch classes, the octave boundaries land on exact integers:</li></ul><table tabindex="0"><thead><tr><th>Interval</th><th>Grid ratio</th><th>Frequency ratio</th><th>Cents</th><th>Deviation</th></tr></thead><tbody><tr><td>Unison (P1)</td><td>16/16</td><td>1/1</td><td>0.0</td><td>0.0</td></tr><tr><td>Octave (P8)</td><td>32/16</td><td>2/1</td><td>1200.0</td><td>0.0</td></tr></tbody></table><h2 id="dividing-the-octave-cultural-perspectives" tabindex="-1">Dividing the octave: cultural perspectives <a class="header-anchor" href="#dividing-the-octave-cultural-perspectives" aria-label="Permalink to “Dividing the octave: cultural perspectives”">​</a></h2><p>The octave frame (2:1) is near-universal; what cultures do <strong>inside</strong> it varies beautifully:</p><ul><li><strong>Western classical:</strong> 12 equal semitones; the whole pitch-organization system assumes octave equivalence.</li><li><strong>India:</strong> the <strong>22 shruti</strong> microtones color the octave around the tonic <strong>sa</strong>, the raga&#39;s anchor across octaves.</li><li><strong>Arabic &amp; Persian maqam:</strong> quarter-tone steps within a 24-position framework — subtle emotional nuance, same cycle.</li><li><strong>Indonesia:</strong> gamelan <strong>slendro</strong> (≈5 near-equal steps) and <strong>pelog</strong> (7 unequal steps) divide — and slightly stretch — the octave their own way.</li><li><strong>Thailand:</strong> a <strong>7-tone equidistant</strong> system (≈171.4 cents per step).</li><li><strong>East Asia:</strong> pentatonic frameworks span the octave while emphasizing different internal relationships.</li></ul><p>Same circle, different maps.</p><h2 id="practice-feeling-unison-and-octave" tabindex="-1">Practice: feeling unison and octave <a class="header-anchor" href="#practice-feeling-unison-and-octave" aria-label="Permalink to “Practice: feeling unison and octave”">​</a></h2><p><strong>Exercise 1 — Unison matching.</strong></p><ol><li>Choose a drone (sustained note).</li><li>Sing the matching note.</li><li>Notice how perfect tuning feels versus slightly off (the wobble of beats).</li><li>Practice finding perfect alignment — zero beats.</li></ol><p><strong>Exercise 2 — Octave hopping.</strong></p><ol><li>With your drone, sing the note an octave above.</li><li>Drop back to the original.</li><li>Try the octave below.</li><li>Practice moving between octave positions — &quot;same note, different floor.&quot;</li></ol><p><strong>Exercise 3 — Octave harmonization.</strong></p><ol><li>Have a friend play a simple melody.</li><li>Sing along in unison.</li><li>Sing an octave above.</li><li>Sing an octave below. Notice: unison fuses, octaves widen.</li></ol><p><strong>In a jam:</strong></p><ul><li><strong>Find your octave home.</strong> If the bass holds the low octave, take the one above; if the middle is crowded, drop or jump an octave to create space.</li><li><strong>Double for impact.</strong> Guitarists and keyboardists double solos in octaves; vocalists add an octave for emphasis, power, and clarity.</li><li><strong>Jump for drama.</strong> Octave leaps up for climaxes, down for sudden energy shifts; octave displacement for surprise.</li></ul><h2 id="chromatone-connection" tabindex="-1">Chromatone connection <a class="header-anchor" href="#chromatone-connection" aria-label="Permalink to “Chromatone connection”">​</a></h2><p>On the Chromatone spectrogram, intervals become color relationships:</p><ul><li><strong>Unison</strong> = same color at the same position — one reinforced band.</li><li><strong>Octave</strong> = same color at regularly spaced positions — the cycle made visible.</li></ul><p>With <strong>Chromatone stickers</strong> on your instrument, unison and octave relationships are visually obvious: octaves are quick to find, transposed melodies keep their color pattern, and chords and scales reveal their octave skeleton at a glance. These visual patterns explain why these intervals feel fundamental — they are the most basic relationships in the color/pitch spectrum.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to “Summary”">​</a></h2><ul><li><strong>Interval</strong> = relationship between two pitches; harmonic (together) or melodic (in sequence).</li><li><strong>Unison P1</strong> = 1:1, 0 cents — maximal consonance, easiest to tune; near-unison = maximal dissonance (beats).</li><li><strong>Octave P8</strong> = 2:1, 1200 cents — same pitch class in a new register; the harmonic series&#39; first step.</li><li><strong>Octave equivalence</strong> appears in human infants, rats, and monkeys, is encoded in auditory cortex — and is strengthened (or not) by musical culture.</li><li><strong>Pitch = height × chroma</strong>; the pitch helix, the Shepard tone, and the tritone paradox make the circularity audible.</li><li><strong>The ear&#39;s window ≈ 10 octaves</strong>; the cycle extends hypothetically from rhythm (−4/−5) to light (+40).</li><li><strong>Cultures divide the octave differently</strong> (12, 22, 24, 5, 7 steps…) but keep the 2:1 frame.</li><li><strong>Chromatone</strong> renders both intervals as one color: aligned (unison) or stacked in a regular pattern (octave).</li><li><strong>Practice:</strong> tune by beats, hop octaves, harmonize — and in a jam, choose your octave consciously.</li></ul><h3 id="sources-further-reading" tabindex="-1">Sources &amp; further reading <a class="header-anchor" href="#sources-further-reading" aria-label="Permalink to “Sources &amp; further reading”">​</a></h3><ul><li>Demany &amp; Armand (1984), <em>The perceptual reality of tone chroma in early infancy</em></li><li>Blackwell &amp; Schlosberg (1943), <em>Octave generalization… in the white rat</em></li><li>Wright et al. (2000), <em>Music perception and octave generalization in rhesus monkeys</em></li><li>Cynx (1993), starling octave tests</li><li>Wagner et al. (2023, 2024), marmoset and rat comparisons</li><li>Moerel et al. (2014), <em>Representation of pitch chroma…</em></li><li>Borra et al. (2013), <em>Octave effect in auditory attention</em></li><li>Jacoby &amp; McDermott (2019), <em>Universal and non-universal features of musical pitch…</em></li><li>Shepard (1964), <em>Circularity in judgments of relative pitch</em></li><li>Deutsch (1986), tritone paradox</li><li>Schouten (1940), residue pitch</li><li>Plomp &amp; Levelt (1965), <em>Tonal consonance and critical bandwidth</em></li><li>Ellis (1885), translation of Helmholtz</li><li>Railsback (1938), octave stretch curve.</li></ul>`,27)])}var p=i(d,[[`render`,f]]);export{u as __pageData,p as default};